import type { EmbeddingProvider } from "../../embeddings/embedding-provider.js";
import { cosineSimilarity } from "../../embeddings/internal/cosine-similarity.js";

/**
 * SEMANTIC THEME EVALUATION
 *
 * Checks whether the themes generated by AI cover the themes
 * we expected, even when the wording is different.
 *
 * EXAMPLE INPUT:
 *
 * expectedThemes = ["management", "recognition"]
 * actualThemes   = ["management support", "recognition", "parking"]
 *
 * We'll use these invented similarity scores throughout:
 *
 *                         management support   recognition   parking
 *   management                   0.99              0.10        0.20
 *   recognition                  0.15              1.00        0.05
 *
 * threshold = 0.85
 *
 * HOW IT WORKS:
 *
 * 1. Take the first expected theme: "management".
 * 2. Compare it against all three actual themes.
 * 3. Find the highest score: 0.99 ("management support").
 * 4. Check 0.99 >= 0.85 → PASS.
 * 5. Repeat for "recognition".
 * 6. Return the individual matches and an overall pass/fail.
 *
 * Expected result:
 *
 * {
 *   passed: true,
 *   matches: [
 *     {
 *       expected: "management",
 *       actual: "management support",
 *       similarity: 0.99,
 *       passed: true
 *     },
 *     {
 *       expected: "recognition",
 *       actual: "recognition",
 *       similarity: 1,
 *       passed: true
 *     }
 *   ]
 * }
 *
 * NOTE: Similarity scores are illustrative.
 * A real embedding model may produce different scores.
 */
export const evaluateThemes = async ({
  expectedThemes,
  actualThemes,
  embeddingProvider,
  threshold = 0.85,
}: {
  expectedThemes: readonly string[];
  actualThemes: readonly string[];
  embeddingProvider: EmbeddingProvider;
  threshold?: number;
}): Promise<{
  passed: boolean;
  matches: {
    expected: string;
    actual: string | null;
    similarity: number;
    passed: boolean;
  }[];
}> => {
  /**
   * EMBEDDING CACHE
   *
   * A Map stores a text string alongside its embedding.
   *
   * Example:
   *
   * {
   *   "management"         → [1, 0],
   *   "management support" → [0.9, 0.1],
   *   "recognition"        → [0, 1]
   * }
   *
   * When we encounter the same text again, we reuse its vector
   * instead of asking the embedding provider to generate it again.
   *
   * This cache exists only during this evaluation.
   */
  const embeddingCache = new Map<string, number[]>();

  /**
   * Returns the embedding for a piece of text.
   *
   * If we've already generated it, use the cached version.
   * Otherwise, generate it and save it for later comparisons.
   */
  const getEmbedding = async (text: string): Promise<number[]> => {
    const cached = embeddingCache.get(text);

    // Example: "recognition" has already been processed.
    // Return its existing vector without another provider call.
    if (cached !== undefined) {
      return cached;
    }

    // First time encountering this text:
    // generate its embedding and store it.
    const embedding = await embeddingProvider.embed(text);

    embeddingCache.set(text, embedding);

    return embedding;
  };

  // Stores the best matching actual theme for each expected theme.
  // Initially: []
  const matches = [];

  /**
   * STEP 1 — LOOP THROUGH EXPECTED THEMES
   *
   * First iteration: expected = "management"
   * Second iteration: expected = "recognition"
   *
   * We're asking:
   * "Does the AI output contain something with a similar meaning
   *  to each theme we expected?"
   */
  for (const expected of expectedThemes) {
    /**
     * STEP 2 — PREPARE TO FIND THE BEST MATCH
     *
     * For "management":
     *
     * bestMatch = null
     * bestSimilarity = -Infinity
     *
     * -Infinity guarantees that the first valid similarity score
     * (which can range from -1 to 1) becomes the initial best.
     */
    let bestMatch: string | null = null;
    let bestSimilarity = -Infinity;

    /**
     * STEP 3 — COMPARE AGAINST EVERY ACTUAL THEME
     *
     * When expected = "management", we compare:
     *
     *   management ↔ management support = 0.99
     *   management ↔ recognition        = 0.10
     *   management ↔ parking            = 0.20
     *
     * Each comparison:
     *   text → embeddings → cosine similarity → score
     */
    for (const actual of actualThemes) {
      // Get embeddings for both themes.
      // If either theme has already been processed, reuse its vector.
      //
      // Example:
      //   expected = "management"
      //   actual   = "management support"
      //
      // First comparison:
      //   getEmbedding("management")         → generates [1, 0]
      //   getEmbedding("management support") → generates [0.9, 0.1]
      //
      // Later comparisons involving "management" reuse [1, 0].
      const expectedEmbedding = await getEmbedding(expected);
      const actualEmbedding = await getEmbedding(actual);

      // Compare the numerical vectors directly.
      // No additional embedding generation happens here.
      const similarity = cosineSimilarity(expectedEmbedding, actualEmbedding);

      /**
       * STEP 4 — KEEP THE HIGHEST SCORING MATCH
       *
       * First comparison:
       *   0.99 > -Infinity
       *   bestMatch = "management support"
       *   bestSimilarity = 0.99
       *
       * Second comparison:
       *   0.10 > 0.99? No, keep existing match.
       *
       * Third comparison:
       *   0.20 > 0.99? No, keep existing match.
       *
       * Final best match for "management":
       *   "management support" (0.99)
       */
      if (similarity > bestSimilarity) {
        bestSimilarity = similarity;
        bestMatch = actual;
      }
    }

    /**
     * STEP 5 — CHECK THE THRESHOLD
     *
     * Our threshold is 0.85.
     *
     * For "management":
     *   0.99 >= 0.85 → true
     *
     * For "recognition":
     *   1.00 >= 0.85 → true
     *
     * If no actual themes were provided, bestMatch stays null,
     * so the expected theme automatically fails.
     */
    const passed = bestMatch !== null && bestSimilarity >= threshold;

    /**
     * STEP 6 — SAVE THE RESULT
     *
     * After evaluating "management":
     *
     * matches = [
     *   {
     *     expected: "management",
     *     actual: "management support",
     *     similarity: 0.99,
     *     passed: true
     *   }
     * ]
     *
     * After evaluating "recognition", matches contains two results.
     *
     * If there was no actual theme to compare, use a score of 0
     * to indicate that no similarity calculation took place.
     */
    matches.push({
      expected,
      actual: bestMatch,
      similarity: bestMatch === null ? 0 : bestSimilarity,
      passed,
    });
  }

  /**
   * STEP 7 — RETURN THE OVERALL RESULT
   *
   * matches.every(...) checks that ALL expected themes passed.
   *
   * Example:
   *   [true, true]  → overall passed = true
   *   [true, false] → overall passed = false
   *
   * This means one missing expected theme fails the evaluation.
   *
   * Note: Extra actual themes are currently allowed.
   * We only check whether all expected themes are covered.
   */
  return {
    passed: matches.every((match) => match.passed),
    matches,
  };
};
